This is odd indeed, the AppImage compiled properly when I applied NO_STRIP through the Terminal and not lib.rs

```rs
pub fn run() {
    std::env::set_var("NO_STRIP", "true");
    std::env::set_var("WEBKIT_DISABLE_COMPOSITING_MODE", "1"); // alternatively `WEBKIT_DISABLE_COMPOSITING_MODE` if this one is not enough

    tauri::Builder::default()
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![greet])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
```
